import org.joda.time.chrono.ISOChronology;
import org.joda.time.field.FieldUtils;
import org.joda.time.format.ISOPeriodFormat;
import org.joda.time.format.PeriodFormatter;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class Period_normalizedStandard_TriageGen1Test {













    @Test
    public void testNormalizedStandard_LargeMillis() {
        // Test the long overflow protection (though the comment says it won't happen)
        // 10000 days is a large number of millis
        Period period = new Period(10000, 0, 0, 0, 0, 0, 0, 0, PeriodType.standard());
        Period result = period.normalizedStandard(PeriodType.standard());

        // 10000 days is roughly 27 years.
        // The logic calculates millis first, then applies years/months.
        // Result should still represent the same duration.
        assertTrue(result.getMillis() >= 0);
        assertEquals(10000, result.getDays() + (result.getWeeks() * 7)); 
        // Note: exact day count might vary due to how Period handles weeks/days, 
        // but the total duration in millis should be preserved.
    }
}
